const esc = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

/** The nav lockup brand.css styles: .brand-mark (MARK_32) then .brand-name (the drawn capitals). With opts.href it comes wrapped in a.brand. */
export function lockup(name, opts = {}) {
  const entry = NAMES[name];
  if (!entry) throw new Error(`lockup: unknown name ${JSON.stringify(name)}; expected one of ${Object.keys(NAMES).join(', ')}`);
  const inner = `<span class="brand-mark">${MARK_32}</span><span class="brand-name">${entry.wordmark}</span>`;
  if (opts.href === undefined) return inner;
  return `<a class="brand" href="${esc(opts.href)}" aria-label="${esc(opts.label ?? entry.label)}">${inner}</a>`;
}
